insert into public.lagrada_stories (id, display_order, story, published) values ('messi-fifty', 0, '{"id":"messi-fifty","category":"EXTRAORDINARY SEASONS","title":"The season of fifty.","subtitle":"One player. Fifty league goals. And a title that went somewhere else.","read":"2 min read","year":"2011/12","related":["messi","ronaldo","xavi"],"source":"https://www.fcbarcelona.com/en/football/first-team/news/2070529/leo-messi-fc-barcelonas-historic-record-breaker","sourceName":"FC Barcelona: Messi’s historical records","paragraphs":["Fifty goals in a single league season sounds like a number from a video game. In 2011/12, Lionel Messi made it a real entry in Spanish football’s record book. It remains the defining number of an astonishing Barcelona campaign.","Think of what that total asks of a forward: scoring again before the last performance has faded from memory, solving a different defence each week, and turning exceptional moments into a routine. The number is striking; its repetition is the remarkable part.","Yet individual brilliance and a team’s final position tell different stories. Real Madrid won that league campaign. A player can produce a season for the ages without his club lifting the trophy. That tension is part of what makes revisiting 2011/12 so interesting.","When comparing great players, always check the frame around the number. Fifty refers to La Liga goals in one season—not all competitions, and not a calendar year. The distinction makes this particular feat more, not less, remarkable."],"extraSource":"https://www.laliga.com/noticias/todos-los-campeones-de-la-historia-de-laliga"}'::jsonb, true) on conflict (id) do nothing;
insert into public.lagrada_stories (id, display_order, story, published) values ('basque-beginnings', 1, '{"id":"basque-beginnings","category":"RIVALRIES & ROOTS","title":"A derby from the very beginning.","subtitle":"Athletic Club and Real Sociedad were there when the league’s story began.","read":"2 min read","year":"1929","related":["aduriz","silva","griezmann"],"source":"https://www.realsociedad.eus/en/club/history","sourceName":"Real Sociedad: club history","paragraphs":["On 10 February 1929, Real Sociedad began life in Spain’s new national league against Athletic Club. The venue was Atotxa in San Sebastián. Their rivalry was not something added later to an established competition: it was part of the opening chapter.","The Basque derby gives a different route into Spanish football from the familiar Barcelona–Madrid axis. Two clubs, two cities and generations of supporters share a regional setting while carrying distinct identities.","Real Sociedad’s history also records an individual landmark from that first season. Paco Bienzobas finished as the league’s leading scorer. Before today’s vast statistics pages, there was already a story about a player and a number worth remembering.","Following this derby across time is a reminder that a fixture can be more than ninety minutes. Stadiums change, squads come and go, but the meeting itself connects one generation of fans with another."]}'::jsonb, true) on conflict (id) do nothing;
insert into public.lagrada_stories (id, display_order, story, published) values ('deportivo-title', 2, '{"id":"deportivo-title","category":"BEYOND THE BIG TWO","title":"When the title went to A Coruña.","subtitle":"Revisit the 1999/00 table and find a different name at the top.","read":"1 min read","year":"1999/00","related":["rivaldo","villa"],"source":"https://www.laliga.com/noticias/todos-los-campeones-de-la-historia-de-laliga","sourceName":"La Liga: historical champions","paragraphs":["In the 1999/00 season, Deportivo La Coruña finished top of La Liga with 69 points. Barcelona finished second with 64. It is a compact table entry with a much bigger implication: Spanish football’s history is not only a conversation between its two most globally familiar clubs.","A title turns a particular squad and a particular season into a permanent reference point. For supporters, the year becomes shorthand. You can say “1999/00” and bring an entire campaign back into view.","That is the pleasure of looking beyond an all-time ranking. Instead of asking who won the most, ask who interrupted the pattern. Deportivo’s championship offers an excellent place to start."]}'::jsonb, true) on conflict (id) do nothing;
insert into public.lagrada_stories (id, display_order, story, published) values ('valencia-years', 3, '{"id":"valencia-years","category":"EXTRAORDINARY SEASONS","title":"Valencia’s double chapter.","subtitle":"Two league titles in three seasons, before the Villa and Silva years.","read":"1 min read","year":"2001–2004","related":["villa","silva","joaquin"],"source":"https://www.laliga.com/noticias/todos-los-campeones-de-la-historia-de-laliga","sourceName":"La Liga: historical champions","paragraphs":["Valencia won La Liga in 2001/02 and again in 2003/04. Those two championships reward a closer look at an era that can slip past fans who discovered Spanish football through later superstar rivalries.","The timing matters. David Villa’s Valencia spell began in 2005, after those titles. David Silva’s first-team breakthrough also belongs to the following chapter. Famous names associated with a club are not automatically members of every celebrated squad.","Football history becomes more interesting when we resist collapsing twenty years into a single imaginary team. A club is a sequence of changing groups. Valencia’s championship years and the later Villa–Silva era are connected chapters, each worth understanding on its own."]}'::jsonb, true) on conflict (id) do nothing;
insert into public.lagrada_stories (id, display_order, story, published) values ('first-champion', 4, '{"id":"first-champion","category":"THE ORIGIN STORIES","title":"Before the global stage.","subtitle":"The national league began in 1929. Barcelona took the first crown.","read":"1 min read","year":"1929","related":["messi","puyol","xavi"],"source":"https://rfef.es/es/noticias/historia-de-la-liga-espanola-los-primeros-anos-1929-1936","sourceName":"RFEF: the league’s first years","paragraphs":["Spanish league football’s opening championship in 1929 went to FC Barcelona. It is a useful starting point for a competition now followed far beyond Spain: a first season, a first table, a first champion.","The early years were not simply a preview of the modern balance of power. Athletic Club won the championships of 1930, 1931, 1934 and 1936. Looking at those early winners changes the shape of the story.","History is more than a long list of familiar badges. Start at the beginning and the foreground shifts: different clubs, different players and a different football world. Today’s game inherits that entire past, not just its most famous recent decades."]}'::jsonb, true) on conflict (id) do nothing;
insert into public.lagrada_stories (id, display_order, story, published) values ('rivaldo-connection', 5, '{"id":"rivaldo-connection","category":"PLAYER CONNECTIONS","title":"The stop before Barcelona.","subtitle":"Rivaldo’s Spanish story began in A Coruña.","read":"1 min read","year":"1996–1997","related":["rivaldo","ronaldinho","r9"],"source":"https://www.fcbarcelona.es/es/futbol/barca-legends/players/1198163/rivaldo","sourceName":"FC Barcelona: Rivaldo profile","paragraphs":["Rivaldo joined Barcelona in 1997 from Deportivo La Coruña. That earlier Spanish stop is an excellent guessing-game clue: a famous player, a less immediately remembered club, and a connection hiding in plain sight.","At Barcelona he became a central figure, winning major honours and the 1999 Ballon d’Or. But reading a career only backwards from its most famous years can make the route there disappear.","Try following careers sideways instead. Rivaldo links Deportivo to Barcelona; Ronaldo links Barcelona to Real Madrid; David Villa links Valencia, Barcelona and Atlético. Each player is a way of moving through the league’s history. The next interesting story may be one club away."]}'::jsonb, true) on conflict (id) do nothing;
